def choose_move(observation):
    x, y = observation['self_position']
    width, height = observation['grid_width'], observation['grid_height']
    resources = observation.get('resources', [])
    opponent_x, opponent_y = observation.get('opponent_position', [0, 0])
    obstacles = set(tuple(obs) for obs in observation.get('obstacles', []))
    def dist(a, b): return abs(a[0]-b[0]) + abs(a[1]-b[1])
    def move_towards(target):
        dx = target[0] - x
        dy = target[1] - y
        move_x = (dx // abs(dx)) if dx != 0 else 0
        move_y = (dy // abs(dy)) if dy != 0 else 0
        if abs(dx) >= abs(dy):
            return (move_x, 0)
        else:
            return (0, move_y)
    # Choose target resource
    target = None
    min_d = float('inf')
    for res in resources:
        td = dist((x, y), (res['x'], res['y']))
        if td < min_d:
            min_d = td
            target = (res['x'], res['y'])
    if target:
        dx, dy = move_towards(target)
    else:
        # No resources, move away from opponent if close
        if dist((x, y), (opponent_x, opponent_y)) <= 2:
            dx = 0
            dy = 0
            if opponent_x > x:
                dx = -1
            elif opponent_x < x:
                dx = 1
            if opponent_y > y:
                dy = -1
            elif opponent_y < y:
                dy = 1
        else:
            dx, dy = 0, 0
    nx, ny = x + dx, y + dy
    if (nx, ny) in obstacles or nx < 0 or ny < 0 or nx >= width or ny >= height:
        return [0, 0]
    return [dx, dy]
